function errorText(error) {const pair = errorMessages[error.code]; return pair ? t(...pair) : t("عملیات انجام نشد؛ دوباره تلاش کن.","The action could not be completed. Please try again.");}
async function api(path, method="GET", data) {
 const response = await fetch(path, {method, credentials:"same-origin", headers:{...(data !== undefined ? {"Content-Type":"application/json"} : {}), ...(state.csrf ? {"X-CSRF-Token":state.csrf} : {})}, ...(data !== undefined ? {body:JSON.stringify(data)} : {})});
 const result = await response.json().catch(() => ({}));
 if (!response.ok) {const error = new Error(result.error || "service_unavailable"); error.code=result.error || "service_unavailable"; error.status=response.status; throw error;}
 return result;
}
let toastTimer;
function toast(message, error=false) {
 clearTimeout(toastTimer);
 if ($("modal").open) {
  // A modal dialog is in the browser's top layer; body toasts sit behind it.
  let feedback = $("modal-feedback");
  if (!feedback) {
   feedback = document.createElement("div");
   feedback.id = "modal-feedback";
   const footer = $("modal-body").querySelector(".modal-footer");
   if (footer) footer.before(feedback);
   else $("modal-body").append(feedback);
  }
  feedback.className = error ? "notice red" : "notice";
  feedback.setAttribute("role", error ? "alert" : "status");
  feedback.textContent = message;
  $("toast").hidden = true;
  feedback.scrollIntoView({block:"nearest"});
  return;
 }
 $("toast").textContent=message;
 $("toast").classList.toggle("error",error);
 $("toast").hidden=false;
 toastTimer=setTimeout(() => $("toast").hidden=true,5500);
}
async function busy(element, action) {
 if (element?.disabled) return;
 const label = element?.innerHTML;
 if (element) {
  element.disabled=true;
  element.setAttribute("aria-busy","true");
  if (element.form && element.type === "submit") element.textContent=t("در حال ارسال…","Submitting…");
 }
 try {await action();}
 catch(error) {
  if(error.status===401) showLogin();
  toast(errorText(error),true);
 } finally {
  if(element?.isConnected) {
   element.disabled=false;
   element.removeAttribute("aria-busy");
   element.innerHTML=label;
  }
 }
}
