function dailyCard() {const me=state.me;const wait=Math.max(0,me.daily_available_at-now()); const locked=me.referrals<me.required_referrals||!me.registered; const disabled=wait>0||locked||me.paused;const label=locked?t(`پس از ${n(me.required_referrals)} دعوت فعال می‌شود`,`Unlocks after ${n(me.required_referrals)} referrals`):wait>0?t(`${n(Math.floor(wait/3600))} ساعت و ${n(Math.ceil((wait%3600)/60))} دقیقه دیگر`,`${Math.floor(wait/3600)}h ${Math.ceil((wait%3600)/60)}m remaining`):t("دریافت پاداش روزانه","Claim daily reward");
 return `<article class="card daily-card"><div class="card-top"><div><h3>${e(t("هر روز، یک قدم نزدیک‌تر","A little closer, every day"))}</h3><p>${e(t("پاداش روزانه حساب تو","Your daily community reward"))}</p></div><span class="icon-tile">${icon("gift")}</span></div><div class="daily-amount number">${n(me.daily_reward)}<small>PRS</small></div><button class="btn soft" data-action="daily" ${disabled?"disabled":""}>${icon(wait?"clock":"gift")}${e(label)}</button></article>`;
}
function missionCard(mission) {const active=["available","attempted","rejected"].includes(mission.status)&&mission.attempts_left>0;return `<article class="card mission-card"><div class="card-top"><div class="mission-title-wrap"><span class="icon-tile ${mission.kind==="quiz"?"red":""}">${icon(mission.kind==="quiz"?"book":"idea")}</span><h3>${e(field(mission,"title"))}</h3></div><span class="badge">${e(recurrence(mission.recurrence))}</span></div><p>${e(field(mission,"description"))}</p><div class="mission-meta"><span>${e(mission.kind==="quiz"?t("تأیید خودکار","Automatic review"):t("بررسی مدیر","Admin review"))}</span>${mission.ends_at?`<span>${e(t("تا ","Until ")+date(mission.ends_at,true))}</span>`:""}<span>${n(mission.remaining_places)} ${e(t("ظرفیت باقی‌مانده","places left"))}</span></div>${mission.reason?`<p class="positive-text">${e(mission.reason)}</p>`:""}<div class="mission-bottom"><div class="reward number">+${n(mission.reward)}<small>PRS</small></div>${active?`<button class="btn ghost small" data-action="open-mission" data-id="${e(mission.id)}">${e(t("شروع مأموریت","Start mission"))}${icon("arrow")}</button>`:statusBadge(mission.status)}</div></article>`;}
function historyList(items) {return items.length?items.map(h=>`<div class="timeline-item"><span class="icon-tile ${h.amount>0?"green":""}">${icon(h.kind==="payment"?"wallet":h.kind==="daily"?"gift":"check")}</span><div class="timeline-copy"><strong>${e(h.title)}</strong><span>${e(date(h.created_at,true))}</span></div><span class="timeline-amount number ${h.amount<0?"negative":""}">${h.amount>0?"+":""}${n(h.amount)} <small>PRS</small></span></div>`).join(""):empty(t("فعالیت‌های تازه‌ات اینجا نمایش داده می‌شوند.","Your new activities will appear here."),"clock");}
function renderDashboard() {const me=state.me;const available=state.missions.filter(m=>["available","attempted","rejected"].includes(m.status)); const preview=(available.length?available:state.missions).slice(0,2);return `${heading("YOUR PRS JOURNEY",t("سلام، به جمع PRS خوش آمدی","Welcome to your PRS journey"),t("فعالیت‌ها، دعوت‌ها و پاداش‌هایت را یک‌جا دنبال کن.","Your activities, referrals, and rewards. All in one place."))}${me.paused?`<div class="notice red">${icon("info")}${e(t("کمپین موقتاً متوقف شده؛ اطلاعات حسابت همچنان قابل مشاهده است.","The campaign is paused. Your account information remains available."))}</div>`:""}<div class="hero-grid"><article class="balance-card"><div class="hero-watermark" aria-hidden="true">PRS</div><div><div class="balance-top">${icon("wallet")}${e(t("موجودی ذخیره‌شده","STORED REWARD BALANCE"))}</div><div class="hero-amount number">${n(me.unpaid)}<span>PRS</span></div><div class="balance-caption">${e(t("موجودی حساب پس از کسر پرداخت‌های انجام‌شده","Account rewards after completed payments"))}</div></div><div class="balance-bottom"><span>${e(t("پرداخت‌نشده: ","Unpaid: "))}${n(me.unpaid)} PRS</span><button class="text-link" data-action="navigate" data-route="account">${e(t("جزئیات حساب ←","Account details →"))}</button></div></article>${dailyCard()}</div>${me.announcement?`<div class="notice portal-announcement">${e(me.announcement)}</div>`:""}${miningCard(true)}<div class="stats-grid"><article class="card stat-card"><span class="icon-tile red">${icon("users")}</span><div><span class="stat-label">${e(t("دعوت‌های ثبت‌شده","Your referrals"))}</span><div class="stat-value number">${n(me.referrals)}<small>${e(t("نفر","people"))}</small></div></div></article><article class="card stat-card"><span class="icon-tile">${icon("trophy")}</span><div><span class="stat-label">${e(t("رتبه تو در جامعه","Your community rank"))}</span><div class="stat-value number">${me.rank?n(me.rank):"—"}<small>${e(t("رتبه","rank"))}</small></div></div></article><article class="card stat-card"><span class="icon-tile green">${icon("check")}</span><div><span class="stat-label">${e(t("پاداش پرداخت‌شده","Payments recorded"))}</span><div class="stat-value number">${n(me.paid)}<small>PRS</small></div></div></article></div><div class="section-heading"><div><h2>${e(t("فرصت بعدی برای مشارکت","Your next contribution"))}</h2><p>${e(t("هر مأموریت، یک فرصت تازه برای همراهی","Every mission is a new way to take part"))}</p></div><button data-action="navigate" data-route="missions">${e(t("همه مأموریت‌ها ←","All missions →"))}</button></div><div class="mission-grid">${preview.length?preview.map(missionCard).join(""):empty(t("مأموریت‌های جدید به‌زودی اینجا نمایش داده می‌شوند.","New missions will appear here when published."))}</div><div class="bottom-grid"><article class="card"><div class="section-heading"><h2>${e(t("آخرین فعالیت‌ها","Recent activity"))}</h2><button data-action="navigate" data-route="account">${e(t("مشاهده حساب","View account"))}</button></div>${historyList(me.history.slice(0,3))}</article><article class="card progress-card"><span class="eyebrow dark">STRONGER TOGETHER</span><h2>${e(t("دوستانت را همراه کن","Bring your community along"))}</h2><p>${e(t("لینک اختصاصی‌ات را با دوستان علاقه‌مند به PRS به اشتراک بگذار و وضعیت دعوت‌هایت را دنبال کن.","Share your personal link with friends interested in PRS and follow your referrals."))}</p><div class="progress-label"><span>${e(t("حدنصاب فعلی کمپین","Current campaign requirement"))}</span><span>${n(me.referrals)} / ${n(me.required_referrals)}</span></div><progress max="${me.required_referrals}" value="${Math.min(me.referrals,me.required_referrals)}"></progress><button class="text-link" data-action="navigate" data-route="referrals">${e(t("دریافت لینک دعوت ←","Get your referral link →"))}</button></article></div>`;}
function renderMissions() {const list=state.missions.filter(m=>state.filter==="all"|| (state.filter==="available"?["available","attempted","rejected"].includes(m.status):state.filter==="completed"?m.status==="completed":m.status==="pending"));return `${heading("MAKE YOUR NEXT MOVE",t("مأموریت‌های تو","Your missions"),t("انتخاب کن، انجام بده و پاداشت را دنبال کن.","Choose a mission, contribute, and follow your reward."))}<div class="tabs">${[["all",t("همه","All")],["available",t("آماده انجام","Available")],["pending",t("در انتظار بررسی","In review")],["completed",t("تکمیل‌شده","Completed")]].map(([key,label])=>`<button class="tab ${state.filter===key?"active":""}" data-action="filter" data-filter="${key}">${e(label)}</button>`).join("")}</div><div class="mission-grid">${list.length?list.map(missionCard).join(""):empty(t("در این بخش مأموریتی وجود ندارد.","No missions in this category."))}</div><p class="switch-hint">${e(t(`مأموریت‌های روزانه و هفتگی براساس منطقه زمانی ${state.config.timezone} محاسبه می‌شوند.`, `Daily and weekly missions use the ${state.config.timezone} timezone.`))}</p>`;}
function renderReferrals() {const me=state.me;return `${heading("GROW THE COMMUNITY",t("دعوت دوستان","Invite your friends"),t("همراهی با آدم‌هایی که به PRS علاقه دارند.","Connect with people who are interested in PRS."))}<div class="split-grid"><article class="card referral-hero"><span class="icon-tile">${icon("users")}</span><h2>${e(t("یک لینک، شروع یک همراهی","One link. A new connection."))}</h2><p>${e(t("لینک زیر مخصوص حساب توست. دوستت باید از همین لینک وارد ربات شود و مراحل ثبت‌نام را کامل کند.","This link belongs to your account. Your friend should open the bot through it and complete registration."))}</p><div class="ref-link">${e(me.referral_link)}</div><div class="button-group"><button class="btn primary" data-action="copy-ref">${icon("copy")}${e(t("کپی لینک دعوت","Copy referral link"))}</button><button class="btn ghost" data-action="share-ref">${e(t("اشتراک‌گذاری","Share link"))}</button></div></article><article class="card"><h2>${e(t("مسیر دعوت در سه قدم","Three steps to a referral"))}</h2><ol class="steps"><li><span class="step-number">${n(1)}</span><div><strong>${e(t("لینکت را به اشتراک بگذار","Share your personal link"))}</strong><p>${e(t("برای دوستانی بفرست که مایل به آشنایی با پروژه‌اند.","Send it to friends who want to discover the project."))}</p></div></li><li><span class="step-number">${n(2)}</span><div><strong>${e(t("ثبت‌نام از طریق ربات","Registration through the bot"))}</strong><p>${e(t("دعوت طبق شرایط ثبت‌نام فعلی ربات به حساب تو اضافه می‌شود.","The referral is recorded under the bot's current registration rules."))}</p></div></li><li><span class="step-number">${n(3)}</span><div><strong>${e(t("پیگیری در هر دو مسیر","Follow your progress anywhere"))}</strong><p>${e(t("تعداد دعوت‌ها و پاداش‌ها در ربات و سایت مشترک است.","Your referral counts and rewards are shared across the bot and website."))}</p></div></li></ol></article></div><div class="stats-grid"><article class="card stat-card"><span class="icon-tile red">${icon("users")}</span><div><span class="stat-label">${e(t("دعوت‌های تو","Your referrals"))}</span><div class="stat-value">${n(me.referrals)}</div></div></article><article class="card stat-card"><span class="icon-tile">${icon("target")}</span><div><span class="stat-label">${e(t("حدنصاب فعلی","Current requirement"))}</span><div class="stat-value">${n(me.required_referrals)}</div></div></article><article class="card stat-card"><span class="icon-tile green">${icon("check")}</span><div><span class="stat-label">${e(t("وضعیت حدنصاب","Requirement status"))}</span><div class="stat-value"><small>${e(me.referrals>=me.required_referrals?t("تکمیل شده","Reached"):t("در مسیر تکمیل","In progress"))}</small></div></div></article></div><div class="notice">${icon("info")}${e(t("دعوت از خود و حساب‌های تکراری می‌تواند باعث رد پاداش شود. شرایط نهایی هر کمپین را پیش از شرکت بخوان.","Self-referrals and duplicate accounts may make rewards ineligible. Read each campaign's terms before taking part."))}</div>`;}
function renderSocial() {
 const links=[
  {title:"PRS TOKEN",subtitle:t("وب‌سایت رسمی پروژه","Official project website"),url:"https://www.prstoken.com",mark:"◆"},
  {title:"X / TWITTER",subtitle:t("خبرها و اطلاعیه‌ها","News and announcements"),url:"https://x.com/PersepolisPRS",mark:"𝕏"},
  {title:"INSTAGRAM",subtitle:t("صفحه رسمی جامعه PRS","Official PRS community"),url:"https://instagram.com/Persepolistoken6",mark:"◎"}
 ];
 return `${heading("PRS OFFICIAL CHANNELS",t("شبکه‌های اجتماعی PRS","PRS social networks"),t("از مسیرهای رسمی پروژه با ما در ارتباط باش.","Connect through our official channels."))}<div class="prs-social-page">${links.map(link=>`<a class="prs-social-card" href="${e(link.url)}" target="_blank" rel="noopener noreferrer"><span class="prs-social-card-mark">${link.mark}</span><span class="prs-social-card-content"><strong>${e(link.title)}</strong><small>${e(link.subtitle)}</small></span><span class="prs-social-card-arrow" aria-hidden="true">↗</span></a>`).join("")}</div>`;
}
function renderLeaderboard() {return `${heading("THE COMMUNITY BOARD",t("رتبه‌بندی جامعه PRS","The PRS leaderboard"),t("برترین حساب‌ها براساس پاداش ثبت‌شده و تعداد دعوت‌ها.","Leading accounts by recorded rewards, then referrals."))}<article class="card"><div class="section-heading"><h2>${e(t("۲۰ حساب برتر","Top 20 accounts"))}</h2><span class="badge gold">${e(t("رتبه تو: ","Your rank: "))}${state.me.rank?n(state.me.rank):"—"}</span></div><div class="table-wrap"><table class="leaderboard"><thead><tr><th>${e(t("رتبه","Rank"))}</th><th>${e(t("حساب","Account"))}</th><th>${e(t("دعوت‌ها","Referrals"))}</th><th>${e(t("پاداش کسب‌شده","Rewards earned"))}</th></tr></thead><tbody>${state.rows.map(row=>`<tr class="${row.is_me?"me":""}"><td><span class="rank-number ${row.rank<=3?"top":""}">${n(row.rank)}</span></td><td><span class="leader-name">${e(row.label)}</span> ${row.is_me?`<span class="badge red">${e(t("تو","You"))}</span>`:""}</td><td>${n(row.referrals)}</td><td class="number">${n(row.earned)} <small>PRS</small></td></tr>`).join("")}</tbody></table></div>${!state.rows.length?empty(t("هنوز حسابی برای نمایش وجود ندارد.","No accounts to display yet.")):""}</article><p class="switch-hint">${e(t("برای حفظ حریم خصوصی، حساب‌ها با شناسه نمایشی نشان داده می‌شوند.","Accounts use display identifiers to protect their privacy."))}</p>`;}
function paymentItem(payment) {const tx=safeUrl(`https://bscscan.com/tx/${payment.tx_hash}`);return `<div class="payment-item"><div class="card-top"><strong class="number">${n(payment.amount)} <small>PRS</small></strong>${statusBadge(payment.status)}</div><p>${e(date(payment.created_at,true))}</p>${payment.reason?`<p>${e(payment.reason)}</p>`:""}${payment.tx_hash&&/^0x[0-9a-fA-F]{64}$/.test(payment.tx_hash)?`<a class="text-link" href="${e(tx)}" target="_blank" rel="noopener noreferrer">${e(t("مشاهده تراکنش ↗","View transaction ↗"))}</a>`:""}</div>`;}
function renderAccount() {const me=state.me;const pending=me.payments.some(p=>p.status==="pending");const walletLocked=pending||me.wallet_edits_remaining===0||me.referrals<me.required_referrals;return `${heading("YOUR ACCOUNT",t("حساب و پاداش‌های من","My account & rewards"),t("آدرس کیف پول، پرداخت‌ها و ارتباط با پشتیبانی.","Your wallet address, payment records, and support."))}<article class="card prs-telegram-id"><div><span class="eyebrow dark">TELEGRAM USER ID</span><h2>${e(t("آیدی عددی تلگرام","Telegram numeric ID"))}</h2><strong class="number" dir="ltr">${e(me.user_id)}</strong></div><button class="btn ghost small" type="button" data-action="copy-telegram-id">${icon("copy")}${e(t("کپی آیدی","Copy ID"))}</button></article><div class="split-grid"><article class="card account-card"><h2>${e(t("کیف پول دریافت جایزه","Your reward wallet"))}</h2><form data-form="wallet"><div class="field"><label for="wallet-address">${e(t("آدرس عمومی BNB Chain","BNB Chain public address"))}</label><input id="wallet-address" name="wallet" class="wallet-input" value="${e(me.wallet)}" placeholder="0x…" pattern="0x[a-fA-F0-9]{40}" required maxlength="42" ${walletLocked?"disabled":""}><small>${e(t("شبکه دریافت: BNB Chain · یک‌بار ثبت و یک‌بار اصلاح","BNB Chain · One registration and one edit"))}</small></div><button class="btn primary" type="submit" ${walletLocked?"disabled":""}>${e(t("ذخیره آدرس","Save address"))}</button></form><div class="notice">${icon("shield")}${e(t("برای ثبت کیف پول فقط آدرس عمومی لازم است؛ عبارت بازیابی یا کلید خصوصی ارسال نکن.","Only your public address is needed. Keep recovery phrases and private keys private."))}</div>${pending?`<p class="switch-hint">${e(t("آدرس تا بررسی درخواست پرداخت فعلی ثابت می‌ماند.","The address stays fixed while your payment request is reviewed."))}</p>`:""}</article><article class="card account-card"><div class="card-top"><h2>${e(t("پاداش پرداخت‌نشده","Unpaid rewards"))}</h2><span class="icon-tile red">${icon("wallet")}</span></div><div class="hero-amount number">${n(me.unpaid)}<span>PRS</span></div><p>${e(t("این عدد، پاداش ثبت‌شده حساب توست و موجودی بلاکچینی کیف پولت نیست.","This is your recorded reward balance, rather than your on-chain wallet balance."))}</p><div class="account-actions"><button class="btn primary" data-action="payment" ${pending||me.unpaid<=0||me.referrals<me.required_referrals||!me.wallet?"disabled":""}>${e(pending?t("درخواست در انتظار بررسی","Request in review"):t("درخواست دریافت جایزه","Request a payment"))}</button></div><p class="switch-hint">${e(t(`شرط فعلی درخواست: کیف پول ثبت‌شده و حداقل ${n(me.required_referrals)} دعوت. پرداخت پس از بررسی مدیر انجام می‌شود.`,`Current requirement: a saved wallet and at least ${me.required_referrals} referrals. Payments follow admin review.`))}</p></article></div><div class="bottom-grid"><article class="card account-card"><h2>${e(t("درخواست‌های پرداخت","Payment requests"))}</h2>${me.payments.length?me.payments.map(paymentItem).join(""):empty(t("هنوز درخواستی ثبت نکرده‌ای.","You have not requested a payment yet."),"wallet")}</article><article class="card account-card"><h2>${e(t("تاریخچه فعالیت","Activity history"))}</h2>${historyList(me.history.slice(0,10))}<p class="switch-hint">${e(t("پاداش‌های قبلی ربات در مجموع حساب لحاظ شده‌اند.","Existing bot rewards are included in your account totals."))}</p></article></div><article class="card account-card account-section"><div class="section-heading"><div><h2>${e(t("کنارت هستیم","Here to help"))}</h2><p>${e(t("سؤال یا مشکلت را برای پشتیبانی بنویس.","Send your question or issue to support."))}</p></div>${icon("mail")}</div><form data-form="ticket"><div class="field"><label for="support-message">${e(t("پیام تو","Your message"))}</label><textarea id="support-message" name="message" minlength="10" maxlength="1500" required placeholder="${e(t("موضوع را با جزئیات توضیح بده…","Tell us what happened…"))}"></textarea></div><button class="btn ghost" type="submit">${e(t("ارسال پیام","Send message"))}</button></form>${me.tickets.length?`<div class="account-section">${me.tickets.map(ticket=>`<div class="payment-item"><span class="badge ${ticket.reply?"green":"gold"}">${e(ticket.reply?t("پاسخ داده شد","Answered"):t("در انتظار پاسخ","Awaiting reply"))}</span><p>${e(ticket.message)}</p>${ticket.reply?`<div class="evidence">${e(ticket.reply)}</div>`:""}</div>`).join("")}</div>`:""}</article>`;}
function renderAdminLegacy() {const a=state.admin;if(!a)return `<div class="loading">${e(t("در حال دریافت مدیریت…","Loading management…"))}</div>`;const visible=a.missions.filter(m=>!m.archived),archived=a.missions.filter(m=>m.archived);const missionNames=Object.fromEntries(a.missions.map(m=>[m.id,m.title]));return `${heading("COMMUNITY MANAGEMENT",t("مدیریت کمپین","Campaign management"),t("مأموریت‌ها و درخواست‌ها را از همین‌جا مدیریت کن.","Manage missions and review requests in one place."),`<button class="btn primary" data-action="new-mission">+ ${e(t("مأموریت جدید","New mission"))}</button>`)}<div class="admin-stats">${[[a.users,t("کاربر ثبت‌شده","Registered users")],[visible.length,t("مأموریت","Missions")],[a.submissions.length,t("مدرک در انتظار بررسی","Submissions to review")],[a.payments.length,t("درخواست پرداخت","Payment requests")]].map(([value,label])=>`<article class="card admin-stat"><strong>${n(value)}</strong><span>${e(label)}</span></article>`).join("")}</div><article class="card admin-section"><div class="section-heading"><h2>${e(t("مأموریت‌های کمپین","Campaign missions"))}</h2><span class="badge">${e(t("ذخیره اولیه به‌صورت غیرفعال","New missions start inactive"))}</span></div>${visible.length?visible.map(m=>`<div class="admin-row"><div><h3>${e(field(m,"title"))} <span class="badge ${m.active?"green":""}">${e(m.active?t("فعال","Active"):t("متوقف","Inactive"))}</span></h3><p>${n(m.reward)} PRS · ${e(recurrence(m.recurrence))} · ${e(t("تکمیل‌شده: ","Completed: "))}${n(m.completed)} / ${n(m.max_claims)}</p><p>${e(t("مصرف بودجه: ","Budget spent: "))}${n(m.spent)} / ${n(m.budget)} PRS · ${e(t("رزروشده: ","Reserved: "))}${n(m.reserved||0)}</p></div><div class="admin-row-actions"><button class="btn ghost small" data-action="toggle-mission" data-id="${e(m.id)}" data-active="${m.active?"0":"1"}">${e(m.active?t("توقف","Pause"):t("فعال‌کردن","Activate"))}</button><button class="btn ghost small" data-action="archive-mission" data-id="${e(m.id)}">${e(t("حذف از فهرست","Remove from list"))}</button></div></div>`).join(""):empty(t("اولین مأموریتت را بساز.","Create your first mission."))}</article>${renderMissionArchive(archived)}<article class="card admin-section"><div class="section-heading"><h2>${e(t("مدارک در انتظار بررسی","Submissions to review"))}</h2></div>${a.submissions.length?a.submissions.map(s=>`<div class="admin-row"><div><h3>${e(missionNames[s.mission_id]||t("مأموریت","Mission"))}</h3><p>${e(t("کاربر ","User "))}${e(s.user_id)} · ${n(s.reward)} PRS · ${e(date(s.created_at,true))}</p></div><button class="btn soft small" data-action="review-submission" data-id="${e(s.id)}">${e(t("بررسی مدرک","Review submission"))}</button></div>`).join(""):empty(t("همه مدارک بررسی شده‌اند.","No submissions are waiting."),"check")}</article><article class="card admin-section"><div class="section-heading"><h2>${e(t("درخواست‌های پرداخت","Payment requests"))}</h2></div><div class="notice">${icon("info")}${e(t("پرداخت را خارج از پنل انجام بده و سپس شناسه تراکنش را اینجا ثبت کن. این پنل توکن منتقل نمی‌کند.","Make the transfer outside this portal, then record its transaction hash here. This portal does not transfer tokens."))}</div>${a.payments.length?a.payments.map(p=>`<div class="admin-row"><div><h3>${e(t("کاربر ","User "))}${e(p.user_id)}</h3><p>${n(p.amount)} PRS · ${e(date(p.created_at,true))}</p></div><button class="btn ghost small" data-action="review-payment" data-id="${e(p.id)}">${e(t("بررسی و ثبت","Review & record"))}</button></div>`).join(""):empty(t("درخواست پرداختی در انتظار نیست.","No payment requests are waiting."),"wallet")}</article><article class="card admin-section"><div class="section-heading"><h2>${e(t("پیام‌های پشتیبانی","Support messages"))}</h2></div>${a.tickets.length?a.tickets.map(ticket=>`<div class="admin-row"><div><h3>${e(t("کاربر ","User "))}${e(ticket.user_id)}</h3><p>${e(ticket.message.slice(0,100))}</p></div><button class="btn ghost small" data-action="reply-ticket" data-id="${e(ticket.id)}">${e(t("پاسخ","Reply"))}</button></div>`).join(""):empty(t("پیام بی‌پاسخی وجود ندارد.","No unanswered messages."),"mail")}</article>`;}
function render() {if(!state.me)return;renderNav();const renderers={dashboard:renderDashboard,mining:renderMining,missions:renderMissions,referrals:renderReferrals,leaderboard:renderLeaderboard,account:renderAccount,social:renderSocial,admin:renderAdmin};$("page").innerHTML=(renderers[state.route]||renderDashboard)();decorateHeritageRoute();updatePhaseTwoClocks();}
async function navigate(route) {if(!["dashboard","mining","missions","referrals","leaderboard","account","social","admin"].includes(route))route="dashboard";if(route==="admin"&&!state.me?.is_admin)route="dashboard";state.route=route;history.replaceState(null,"",`#${route}`);if(route==="admin")state.admin=await api("/api/admin/overview");render();$("page").focus({preventScroll:true});window.scrollTo({top:0,behavior:"instant"});}
function showLogin() {if($("modal").open)closeModal();clearHeritageReward();state.me=null;state.csrf="";$("app-shell").hidden=true;$("login-screen").hidden=false;}
async function refresh() {const session=await api("/api/session");state.me=session.profile;state.csrf=session.csrf;state.offset=state.me.server_time-Math.floor(Date.now()/1000);const [missions,board]=await Promise.all([api("/api/missions"),api("/api/leaderboard")]);state.missions=missions.missions;state.rows=board.rows;$("user-avatar").textContent=String(state.me.user_id).slice(-2);$("login-screen").hidden=true;$("app-shell").hidden=false;if(state.route==="admin")state.admin=await api("/api/admin/overview");render();}
function modal(title,html) {$("modal-title").textContent=title;$("modal-body").innerHTML=html;$("modal").showModal();}
function closeModal() {$("modal").close();$("modal-body").innerHTML="";}
function openMission(id) {const m=state.missions.find(item=>item.id===id);if(!m)return;const options=state.lang==="en"&&m.options_en?.length===m.options.length?m.options_en:m.options;modal(field(m,"title"),`<p class="modal-summary">${e(field(m,"description"))}</p>${safeUrl(m.url)?`<p class="account-section"><a class="text-link" href="${e(safeUrl(m.url))}" target="_blank" rel="noopener noreferrer">${e(t("مطالعه منبع مأموریت ↗","Read the mission resource ↗"))}</a></p>`:""}<div class="modal-reward">+${n(m.reward)} PRS</div><form data-form="mission" data-id="${e(m.id)}">${m.kind==="quiz"?`<h3 class="account-section">${e(field(m,"question"))}</h3><div class="quiz-options">${options.map((option,index)=>`<label class="quiz-option"><input type="radio" name="answer" value="${index}" required><span>${e(option)}</span></label>`).join("")}</div><p class="modal-hint">${e(t("تلاش باقی‌مانده: ","Attempts remaining: "))}${n(m.attempts_left)}</p>`:`<div class="field account-section"><label for="mission-evidence">${e(t("لینک اثر یا توضیح فعالیت","Link to your work or activity description"))}</label><textarea id="mission-evidence" name="evidence" minlength="10" maxlength="1500" required></textarea><small>${e(t("پس از ارسال، نتیجه بررسی در همین مأموریت نمایش داده می‌شود.","After submission, the review result will appear on this mission."))}</small></div>`}<div class="modal-footer"><button class="btn ghost" data-action="close-modal" type="button">${e(t("بستن","Close"))}</button><button class="btn primary" type="submit">${e(m.kind==="quiz"?t("ارسال پاسخ","Submit answer"):t("ارسال برای بررسی","Submit for review"))}</button></div></form>`);}
function createMissionModal() {modal(t("ساخت مأموریت جدید","Create a new mission"),`<form data-form="new-mission"><div class="field"><label for="mission-title">${e(t("عنوان مأموریت","Mission title"))}</label><input id="mission-title" name="title" maxlength="100" required></div><div class="field"><label for="mission-description">${e(t("توضیح دقیق فعالیت","Activity instructions"))}</label><textarea id="mission-description" name="description" maxlength="1000" required></textarea></div><div class="form-grid"><div class="field"><label for="mission-kind">${e(t("نوع تأیید","Review type"))}</label><select id="mission-kind" name="kind"><option value="quiz">${e(t("سؤال با تأیید خودکار","Automatically checked question"))}</option><option value="manual">${e(t("ارسال مدرک و بررسی مدیر","Evidence and admin review"))}</option></select></div><div class="field"><label for="mission-recurrence">${e(t("تکرار","Repeat"))}</label><select id="mission-recurrence" name="recurrence"><option value="once">${e(t("یک‌بار برای هر کاربر","Once per user"))}</option><option value="daily">${e(t("هر روز","Daily"))}</option><option value="weekly">${e(t("هر هفته","Weekly"))}</option></select></div></div><div class="form-grid three"><div class="field"><label for="mission-reward">${e(t("پاداش هر تأیید (PRS)","Reward per approval (PRS)"))}</label><input id="mission-reward" name="reward" type="number" min="1" max="300000000" step="1" required></div><div class="field"><label for="mission-budget">${e(t("کل بودجه مأموریت (PRS)","Total mission budget (PRS)"))}</label><input id="mission-budget" name="budget" type="number" min="1" max="300000000" step="1" required></div><div class="field"><label for="mission-capacity">${e(t("سقف تعداد پاداش","Maximum reward claims"))}</label><input id="mission-capacity" name="max_claims" type="number" min="1" max="1000000" step="1" required></div></div><div class="form-grid"><div class="field"><label for="mission-end">${e(t("مهلت پایان به وقت تهران؛ تاریخ میلادی (اختیاری)","Deadline in Tehran time; Gregorian date (optional)"))}</label><input id="mission-end" name="ends_at" type="datetime-local"></div><div class="field"><label for="mission-url">${e(t("لینک منبع (اختیاری)","Resource link (optional)"))}</label><input id="mission-url" name="url" type="url" placeholder="https://…" maxlength="500"></div></div><div id="quiz-fields" class="admin-kind-fields"><div class="field"><label for="mission-question">${e(t("متن سؤال","Question"))}</label><input id="mission-question" name="question" maxlength="500" required></div>${[0,1,2].map(i=>`<div class="field"><label for="option-${i}">${e(t("گزینه ","Option "))}${n(i+1)}</label><input id="option-${i}" name="option_${i}" maxlength="160" required></div>`).join("")}<div class="field"><label for="mission-answer">${e(t("پاسخ صحیح","Correct answer"))}</label><select id="mission-answer" name="answer"><option value="0">${e(t("گزینه اول","Option 1"))}</option><option value="1">${e(t("گزینه دوم","Option 2"))}</option><option value="2">${e(t("گزینه سوم","Option 3"))}</option></select></div></div><details><summary>${e(t("متن انگلیسی (اختیاری)","English translation (optional)"))}</summary><div class="field"><label for="mission-title-en">English title</label><input id="mission-title-en" name="title_en" maxlength="100" dir="ltr"></div><div class="field"><label for="mission-description-en">English instructions</label><textarea id="mission-description-en" name="description_en" maxlength="1000" dir="ltr"></textarea></div><div class="field"><label for="mission-question-en">English question</label><input id="mission-question-en" name="question_en" maxlength="500" dir="ltr"></div>${[0,1,2].map(i=>`<div class="field"><label for="option-en-${i}">English option ${i+1}</label><input id="option-en-${i}" name="option_en_${i}" maxlength="160" dir="ltr"></div>`).join("")}</details><div class="notice">${icon("info")}${e(t("مأموریت ابتدا غیرفعال ذخیره می‌شود. پیش از فعال‌کردن، پاداش و بودجه را بررسی کن. در مأموریت تکرارشونده، بودجه برای مجموع تمام دوره‌هاست.","The mission is saved inactive. Review its reward and budget before activating it. For repeating missions, the budget covers all periods combined."))}</div><div class="modal-footer"><button class="btn ghost" type="button" data-action="close-modal">${e(t("انصراف","Cancel"))}</button><button class="btn primary" type="submit">${e(t("ذخیره مأموریت","Save mission"))}</button></div></form>`);}
function reviewSubmissionModal(id) {const s=state.admin.submissions.find(item=>item.id===id);if(!s)return;modal(t("بررسی مدرک مأموریت","Review mission submission"),`<div class="detail-line"><span>${e(t("کاربر","User"))}</span><span>${e(s.user_id)}</span></div><div class="detail-line"><span>${e(t("پاداش پس از تأیید","Reward on approval"))}</span><strong>${n(s.reward)} PRS</strong></div><div class="evidence">${e(s.evidence)}</div><form data-form="review-submission" data-id="${e(id)}"><div class="field"><label for="review-reason">${e(t("دلیل رد؛ در صورت رد الزامی است","Reason (required for rejection)"))}</label><textarea id="review-reason" name="reason" maxlength="400"></textarea></div><div class="modal-footer"><button class="btn ghost" type="submit" name="decision" value="reject">${e(t("رد مدرک","Reject"))}</button><button class="btn primary" type="submit" name="decision" value="approve">${e(t("تأیید و ثبت پاداش","Approve & record reward"))}</button></div></form>`);}
function reviewPaymentModal(id) {const p=state.admin.payments.find(item=>item.id===id);if(!p)return;modal(t("ثبت نتیجه پرداخت","Record payment outcome"),`<div class="detail-line"><span>${e(t("کاربر","User"))}</span><span>${e(p.user_id)}</span></div><div class="detail-line"><span>${e(t("مبلغ درخواست","Requested amount"))}</span><strong>${n(p.amount)} PRS</strong></div><div class="evidence mono">${e(p.wallet)}</div><div class="notice">${icon("info")}${e(t("این دکمه توکن منتقل نمی‌کند. فقط پرداختی را ثبت کن که خارج از پنل انجام داده‌ای و بررسی کرده‌ای.","This action does not transfer tokens. Only record a transfer you have completed and checked outside this portal."))}</div><form data-form="review-payment" data-id="${e(id)}"><div class="field"><label for="payment-hash">${e(t("شناسه تراکنش انجام‌شده","Completed transfer transaction hash"))}</label><input id="payment-hash" name="tx_hash" class="wallet-input" maxlength="66" placeholder="0x…"></div><div class="field"><label for="payment-reason">${e(t("دلیل رد؛ در صورت رد الزامی است","Reason (required for rejection)"))}</label><textarea id="payment-reason" name="reason" maxlength="400"></textarea></div><div class="modal-footer"><button class="btn ghost" type="submit" name="decision" value="reject">${e(t("رد درخواست","Reject request"))}</button><button class="btn primary" type="submit" name="decision" value="approve">${e(t("ثبت پرداخت انجام‌شده","Record completed payment"))}</button></div></form>`);}
document.addEventListener("click",(event)=>{const button=event.target.closest("[data-action]");if(!button)return;const action=button.dataset.action;if(phaseTwoClick(button))return;if(action==="close-modal"){closeModal();return;}if(action==="filter"){state.filter=button.dataset.filter;render();return;}if(action==="open-mission"){openMission(button.dataset.id);return;}if(action==="new-mission"){createMissionModal();return;}if(action==="review-submission"){reviewSubmissionModal(button.dataset.id);return;}if(action==="review-payment"){reviewPaymentModal(button.dataset.id);return;}if(action==="reply-ticket"){const ticket=state.admin.tickets.find(item=>item.id===button.dataset.id);modal(t("پاسخ پشتیبانی","Reply to support message"),`<div class="evidence">${e(ticket.message)}</div><form data-form="reply-ticket" data-id="${e(ticket.id)}"><div class="field"><label for="ticket-reply">${e(t("پاسخ تو","Your reply"))}</label><textarea id="ticket-reply" name="reply" minlength="3" maxlength="1500" required></textarea></div><button class="btn primary full" type="submit">${e(t("ثبت پاسخ","Save reply"))}</button></form>`);return;}if(action==="payment"){modal(t("درخواست دریافت جایزه","Request a payment"),`<p class="modal-summary">${e(t("درخواست با آدرس فعلی کیف پول و مبلغ زیر ثبت می‌شود. پرداخت پس از بررسی مدیر انجام خواهد شد.","Your request will use your current wallet address and the amount below. Payments follow admin review."))}</p><div class="hero-amount">${n(state.me.unpaid)} <small>PRS</small></div><div class="evidence mono">${e(state.me.wallet)}</div><form data-form="payment"><div class="field"><label for="payment-amount">${e(t("مقدار برداشت PRS","Amount to request PRS"))}</label><input id="payment-amount" name="amount" type="number" min="1" max="${state.me.unpaid}" step="1" value="${state.me.unpaid}" required><small>${e(t("بعد از پرداخت موفق، سطح با موجودی باقی‌مانده محاسبه می‌شود.","After a completed payment, your level uses the remaining balance."))}</small></div><button class="btn primary full" type="submit">${e(t("ثبت درخواست","Submit request"))}</button></form>`);return;}
 busy(button,async()=>{if(action==="navigate")await navigate(button.dataset.route);else if(action==="refresh"){await refresh();toast(t("اطلاعات تازه شد.","Your account is up to date."));}else if(action==="daily"){const result=await api("/api/daily","POST");await refresh();celebrateHeritageReward(result.amount);toast(t(`${n(result.amount)} PRS پاداش ثبت شد.`,`${n(result.amount)} PRS reward recorded.`));}else if(action==="copy-telegram-id"){try{await navigator.clipboard.writeText(String(state.me.user_id));toast(t("آیدی عددی کپی شد.","Telegram ID copied."));}catch{toast(t("کپی خودکار ممکن نیست.","Automatic copy is unavailable."),true);}}else if(action==="copy-ref"){try{await navigator.clipboard.writeText(state.me.referral_link);toast(t("لینک دعوت کپی شد.","Referral link copied."));}catch{modal(t("لینک دعوت تو","Your referral link"),`<div class="field"><label>${e(t("لینک را انتخاب و کپی کن","Select and copy this link"))}</label><input readonly class="wallet-input" value="${e(state.me.referral_link)}"></div>`);}}else if(action==="share-ref"){if(navigator.share){try{await navigator.share({title:"PRS",url:state.me.referral_link});}catch(error){if(error.name!=="AbortError")throw error;}}else{await navigator.clipboard.writeText(state.me.referral_link);toast(t("لینک دعوت کپی شد.","Referral link copied."));}}else if(action==="logout"){await api("/api/auth/logout","POST");showLogin();}else if(action==="demo-user"||action==="demo-admin"){const result=await api("/api/auth/demo","POST",{role:action==="demo-admin"?"admin":"user"});state.csrf=result.csrf;state.route=action==="demo-admin"?"admin":"dashboard";await refresh();}else if(action==="toggle-mission"){await api(`/api/admin/missions/${encodeURIComponent(button.dataset.id)}/active`,"POST",{active:button.dataset.active==="1"});await refresh();toast(t("وضعیت مأموریت تغییر کرد.","Mission status updated."));}});
});
document.addEventListener("change",event=>{if(event.target.id==="mission-kind"){const quiz=event.target.value==="quiz";$("quiz-fields").hidden=!quiz;$("quiz-fields").querySelectorAll("input").forEach(input=>input.required=quiz);}});
document.addEventListener("submit",event=>{const form=event.target.closest("form[data-form]");if(!form)return;event.preventDefault();const submitter=event.submitter;const fd=new FormData(form);const kind=form.dataset.form;if(handlePhaseTwoForm(form,submitter,fd))return;busy(submitter,async()=>{if(kind==="wallet"){await api("/api/wallet","POST",{wallet:fd.get("wallet")});toast(t("آدرس کیف پول ذخیره شد.","Wallet address saved."));}else if(kind==="ticket"){await api("/api/tickets","POST",{message:fd.get("message")});toast(t("پیامت ثبت شد.","Your message was sent."));}else if(kind==="mission"){const mission=state.missions.find(item=>item.id===form.dataset.id);const result=await api(`/api/missions/${encodeURIComponent(form.dataset.id)}/submit`,"POST",mission.kind==="quiz"?{answer:Number(fd.get("answer"))}:{evidence:fd.get("evidence")});closeModal();if(result.status==="completed")celebrateHeritageReward(result.amount);toast(result.status==="completed"?t(`${n(result.amount)} PRS پاداش ثبت شد.`,`${n(result.amount)} PRS reward recorded.`):result.status==="pending"?t("مدرکت برای بررسی ثبت شد.","Your submission is in review."):t("پاسخ اشتباه بود؛ فرصت این دوره تمام شد.","Incorrect answer; this period’s attempt is used."),result.status==="attempted");}else if(kind==="payment"){await api("/api/payments","POST",{amount:Number(fd.get("amount"))});closeModal();toast(t("درخواست پرداخت ثبت شد.","Payment request submitted."));}else if(kind==="new-mission"){const options=[0,1,2].map(i=>String(fd.get(`option_${i}`)||""));const optionsEn=[0,1,2].map(i=>String(fd.get(`option_en_${i}`)||""));const data={title:fd.get("title"),title_en:fd.get("title_en"),description:fd.get("description"),description_en:fd.get("description_en"),kind:fd.get("kind"),recurrence:fd.get("recurrence"),reward:Number(fd.get("reward")),budget:Number(fd.get("budget")),max_claims:Number(fd.get("max_claims")),ends_at_tehran:fd.get("ends_at")||"",url:fd.get("url"),question:fd.get("question")||"",question_en:fd.get("question_en")||"",options,options_en:optionsEn.some(Boolean)?optionsEn:[],answer:Number(fd.get("answer"))};await api("/api/admin/missions","POST",data);closeModal();toast(t("مأموریت ذخیره شد؛ برای نمایش به کاربران، آن را فعال کن.","Mission saved. Activate it when you are ready to publish."));}else if(kind==="review-submission"){await api(`/api/admin/submissions/${encodeURIComponent(form.dataset.id)}/review`,"POST",{approve:submitter.value==="approve",reason:fd.get("reason")});closeModal();toast(t("نتیجه بررسی ثبت شد.","Review saved."));}else if(kind==="review-payment"){await api(`/api/admin/payments/${encodeURIComponent(form.dataset.id)}/review`,"POST",{approve:submitter.value==="approve",reason:fd.get("reason"),tx_hash:fd.get("tx_hash")});closeModal();toast(t("نتیجه پرداخت ثبت شد.","Payment outcome recorded."));}else if(kind==="reply-ticket"){await api(`/api/admin/tickets/${encodeURIComponent(form.dataset.id)}/reply`,"POST",{reply:fd.get("reply")});closeModal();toast(t("پاسخ ثبت شد.","Reply saved."));}await refresh();});});
for(const id of ["login-lang","app-lang"])$(id).addEventListener("click",()=>{state.lang=state.lang==="fa"?"en":"fa";localStorage.setItem("prs-language",state.lang);applyLanguage();render();});
$("modal").addEventListener("click",event=>{if(event.target===$("modal")){const r=$("modal").getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
async function init(){applyLanguage();try{state.config=await api("/api/bootstrap");if(state.config.server_time)state.offset=state.config.server_time-Math.floor(Date.now()/1000);$("demo-actions").hidden=!state.config.demo;$("demo-banner").hidden=!state.config.demo;$("telegram-login").href=safeUrl(state.config.bot_url);applyLanguage();const params=new URLSearchParams(location.hash.slice(1));const token=params.get("token");if(token){history.replaceState(null,"","/");$("login-status").textContent=t("در حال ورود امن…","Signing you in…");const result=await api("/api/auth/exchange","POST",{token});state.csrf=result.csrf;$("login-status").textContent="";}const route=location.hash.slice(1);if(["dashboard","mining","missions","referrals","leaderboard","account","social","admin"].includes(route))state.route=route;await refresh();}catch(error){showLogin();if(error.code!=="login_required")$("login-status").textContent=errorText(error);}}
window.addEventListener("hashchange",()=>{if(state.me)navigate(location.hash.slice(1)).catch(error=>toast(errorText(error),true));});
setInterval(()=>{if(state.me&&state.route==="dashboard"&&!$("modal").open&&!document.hidden)render();},60000);

function tehranClock() {
 return `<span class="tehran-clock" data-tehran-clock></span>`;
}
function updatePhaseTwoClocks() {
 const stamp=new Intl.DateTimeFormat(state.lang==="fa"?"fa-IR":"en-GB",{dateStyle:"medium",timeStyle:"medium",timeZone:"Asia/Tehran"}).format(new Date(now()*1000));
 document.querySelectorAll("[data-tehran-clock]").forEach(node=>node.textContent=`${stamp} · ${t("تهران","Tehran")}`);
 const cycle=state.me?.mining?.cycle;
 if(cycle) {
  const wait=Math.max(0,cycle.ends_at-now());
  document.querySelectorAll("[data-mining-timer]").forEach(node=>node.textContent=wait?`${n(Math.floor(wait/3600))}:${String(Math.floor(wait%3600/60)).padStart(2,"0")}:${String(wait%60).padStart(2,"0")}`:t("آماده دریافت","Ready to collect"));
  document.querySelectorAll('[data-action="mining-claim"]').forEach(node=>node.disabled=wait>0||state.me.paused);
  document.querySelectorAll("[data-mining-progress]").forEach(node=>node.value=Math.min(28800,Math.max(0,now()-cycle.started_at)));
 }
}
const tierMark=id=>({bronze:"🥉",silver:"🥈",gold:"🥇",platinum:"💠",diamond:"💎"}[id]||"✦");
function miningCard(compact=false) {
 const m=state.me.mining;if(!m)return "";
 const cycle=m.cycle,level=m.level,wait=cycle?Math.max(0,cycle.ends_at-now()):0;
 const gated=state.me.referrals<state.me.required_referrals||!/^0x[a-fA-F0-9]{40}$/.test(state.me.wallet||"");
 const disabled=state.me.paused||!state.me.registered||gated||(!cycle&&(!m.enabled||m.budget_remaining<level.reward));
 return `<article class="card mining-card tier-${e(level.id)} ${cycle?"is-mining":""}"><div class="card-top"><div><span class="eyebrow dark">PRS MINING · PHASE 02</span><h2>${e(t("ماین PRS","Mine PRS"))}</h2></div><span class="tier-badge">${tierMark(level.id)} ${e(field(level,"name"))}</span></div><div class="mining-layout"><div><div class="mining-amount number">${n(cycle?cycle.reward:level.reward)} <small>PRS / ${e(t("۸ ساعت","8 hours"))}</small></div><p>${e(cycle?t("دوره فعال است؛ می‌توانی سایت را ببندی.","Your cycle is active. You can close the website."):t("یک دوره شروع کن؛ بعد از ۸ ساعت پاداش را دریافت کن.","Start a cycle and collect your reward after 8 hours."))}</p>${cycle?`<div class="mining-timer number" data-mining-timer>${e(wait?t("در حال ماین…","Mining…"):t("آماده دریافت","Ready to collect"))}</div><progress data-mining-progress max="28800" value="${Math.min(28800,Math.max(0,now()-cycle.started_at))}"></progress><p class="muted">${e(t("پایان دوره به وقت تهران: ","Cycle ends in Tehran time: ")+date(cycle.ends_at,true))}</p>`:`<p class="switch-hint">${e(!m.enabled?t("شروع دوره جدید موقتاً متوقف است.","New cycles are temporarily paused."):m.budget_remaining<level.reward?t("ظرفیت دوره‌های جدید تکمیل شده است.","New-cycle capacity has been reached."):t("پاداش زمان‌دار داخل پنل؛ بدون نیاز به بازماندن صفحه.","Timed portal rewards. No need to keep this page open."))}</p>`}</div><div class="mining-actions">${gated?`<p class="notice red">${e(t("برای ماین: ۳ دعوت معتبر و ثبت کیف پول لازم است. عضویت کانال نیز الزامی است.","Mining requires 3 verified referrals, a saved wallet and channel membership."))}</p>`:""}<button class="btn primary" data-action="${cycle?"mining-claim":"mining-start"}" ${disabled||(cycle&&wait>0)?"disabled":""}>${icon(cycle?"gift":"clock")}${e(cycle?t("دریافت پاداش","Collect reward"):t("شروع ماین ۸ساعته","Start 8-hour cycle"))}</button>${compact?`<button class="btn ghost" data-action="navigate" data-route="mining">${e(t("سطح من و قوانین ماین","My level & mining rules"))}</button>`:""}</div></div></article>`;
}
function renderMining() {
 const m=state.me.mining,level=m.level,next=level.next;
 return `${heading("YOUR MINING JOURNEY",t("ماین و سطح حساب","Mining & account level"),t("دعوت معتبر و موجودی ذخیره‌شده، سطح تو را تعیین می‌کنند.","Verified referrals and your stored balance determine your level."))}${miningCard()}<div class="split-grid account-section"><article class="card"><h2>${tierMark(level.id)} ${e(t("سطح فعلی: ","Current level: ")+field(level,"name"))}</h2><div class="detail-line"><span>${e(t("موجودی ذخیره‌شده","Stored balance"))}</span><strong>${n(level.stored_balance)} PRS</strong></div><div class="detail-line"><span>${e(t("دعوت‌های تأییدشده","Verified referrals"))}</span><strong>${n(state.me.referrals)}</strong></div><div class="detail-line"><span>${e(t("مجموع ماین دریافت‌شده","Mining rewards collected"))}</span><strong>${n(m.total_claimed)} PRS</strong></div>${next?`<h3 class="account-section">${e(t("تا سطح ","Next level: ")+field(next,"name"))}</h3><p>${e(t("هر دو شرط باید کامل شود.","Both requirements must be met."))}</p><div class="progress-label"><span>${e(t("دعوت معتبر","Verified referrals"))}</span><strong>${n(Math.min(state.me.referrals,next.referrals))} / ${n(next.referrals)}</strong></div><progress max="${next.referrals}" value="${Math.min(state.me.referrals,next.referrals)}"></progress><div class="progress-label"><span>${e(t("موجودی ذخیره‌شده","Stored balance"))}</span><strong>${n(Math.min(level.stored_balance,next.balance))} / ${n(next.balance)}</strong></div><progress max="${next.balance}" value="${Math.min(level.stored_balance,next.balance)}"></progress>`:`<p class="positive-text account-section">${e(t("به بالاترین سطح رسیده‌ای.","You have reached the highest level."))}</p>`}</article><article class="card"><h2>${e(t("قوانین ماین","How mining works"))}</h2><ol class="mining-rules"><li>${e(t("هر دوره ۸ ساعت است؛ پس از دریافت باید دوره بعد را خودت شروع کنی.","Each cycle lasts 8 hours. Collect it, then manually start the next cycle."))}</li><li>${e(t("بعد از پایان دوره، پاداش بیشتر جمع نمی‌شود.","Rewards stop accumulating when the cycle ends."))}</li><li>${e(t("پاداش هر دوره با سطح هنگام شروع ثابت می‌شود.","The reward is fixed using your level when the cycle starts."))}</li><li>${e(t("بعد از پرداخت موفق برداشت، سطح با موجودی باقی‌مانده محاسبه می‌شود؛ درخواست ردشده سطح را کم نمی‌کند.","After a completed payment, your level uses the remaining balance. Rejected requests do not lower it."))}</li><li>${e(t("این ماین پاداش داخل پنل است؛ از پردازنده گوشی استفاده نمی‌کند.","Mining earns portal rewards without using your phone's processor."))}</li></ol></article></div><article class="card account-section"><h2>${e(t("سطح‌ها و پاداش هر دوره","Levels & cycle rewards"))}</h2><div class="table-wrap"><table><thead><tr><th>${e(t("سطح","Level"))}</th><th>${e(t("دعوت لازم","Referrals"))}</th><th>${e(t("موجودی لازم","Stored balance"))}</th><th>${e(t("هر ۸ ساعت","Per 8 hours"))}</th></tr></thead><tbody>${m.tiers.map(tier=>`<tr class="${tier.id===level.id?"me":""}"><td>${tierMark(tier.id)} ${e(field(tier,"name"))}</td><td>${n(tier.referrals)}</td><td>${n(tier.balance)} PRS</td><td>${n(tier.reward)} PRS</td></tr>`).join("")}</tbody></table></div></article>`;
}
const adminActionLabel=action=>({campaign_controls:t("تنظیمات کمپین","Campaign controls"),bonus:t("پاداش دستی","Manual reward"),suspend:t("تعلیق حساب","Account suspension"),resume:t("رفع تعلیق","Account restored"),unlock_wallet:t("فرصت اصلاح کیف پول","Wallet edit unlocked"),update_wallet:t("اصلاح کیف پول","Wallet updated"),create_mission:t("ساخت مأموریت","Mission created"),mission_active:t("وضعیت مأموریت","Mission status"),archive_mission:t("حذف مأموریت از فهرست","Mission archived"),restore_mission:t("بازگردانی مأموریت","Mission restored"),review_submission:t("بررسی مدرک","Submission reviewed"),review_payment:t("بررسی پرداخت","Payment reviewed"),reply_ticket:t("پاسخ پشتیبانی","Support reply")}[action]||action);
function renderMissionArchive(missions) {
 if(!missions.length)return "";
 return `<details class="card admin-section"><summary>${e(t("بایگانی مأموریت‌ها","Archived missions"))} (${n(missions.length)})</summary><p class="switch-hint">${e(t("سوابق پاسخ‌ها و پاداش‌ها نگهداری می‌شوند. بازگردانی، مأموریت را به‌صورت غیرفعال برمی‌گرداند.","Answers and rewards are retained. Restored missions remain inactive until you activate them."))}</p>${missions.map(m=>`<div class="admin-row"><div><h3>${e(field(m,"title"))}</h3><p>${e(t("تکمیل‌شده: ","Completed: "))}${n(m.completed)} · ${n(m.spent)} PRS</p></div><button class="btn ghost small" data-action="restore-mission" data-id="${e(m.id)}">${e(t("بازگردانی","Restore"))}</button></div>`).join("")}</details>`;
}
function archiveMissionModal(id) {
 const mission=state.admin.missions.find(m=>m.id===id);if(!mission)return;
 modal(t("حذف مأموریت از فهرست","Remove mission from list"),`<h3>${e(field(mission,"title"))}</h3><p class="modal-summary">${e(t("این مأموریت از فهرست کاربران حذف و در بایگانی مدیریت نگهداری می‌شود. سوابق پاسخ‌ها و پاداش‌ها باقی می‌مانند و می‌توانی آن را بازگردانی کنی.","This mission will be removed from users' lists and kept in the admin archive. Answers and rewards are preserved, and you can restore it."))}</p>${mission.pending?`<p class="notice">${e(t("مدارک در انتظار بررسی همچنان قابل بررسی و پرداخت خواهند بود.","Pending submissions will remain available for review and rewards."))}</p>`:""}<form data-form="archive-mission" data-id="${e(id)}"><div class="modal-footer"><button class="btn primary" type="submit">${e(t("حذف از فهرست","Remove from list"))}</button><button class="btn ghost" type="button" data-action="close-modal">${e(t("انصراف","Cancel"))}</button></div></form>`);
}
function renderTelegramCheck() {
 const check=state.telegramCheck;
 const result=check?`<div class="${check.ok?"notice":"form-feedback is-error"}" role="status"><p>${e(check.ok?t("اتصال تلگرام و دسترسی مدیریت کانال تأیید شد.","Telegram connection and channel admin access are verified."):errorText({code:check.error}))}</p>${check.bot_username?`<p>${e(t("ربات متصل: @","Connected bot: @"))}${e(check.bot_username)}</p>`:""}<p>${e(t("ربات تنظیم‌شده: @","Configured bot: @"))}${e(check.configured_bot_username)} · ${e(check.channel)}</p>${check.user_is_member===false?`<p>${e(t("حساب مدیر در کانال عضو نیست؛ برای دریافت پاداش ابتدا عضو شو.","Your admin account is not a channel member. Join before claiming user rewards."))}</p>`:""}</div>`:"";
 return `<article class="card admin-section"><div class="section-heading"><h2>${e(t("بررسی اتصال تلگرام و عضویت","Telegram & membership check"))}</h2><button class="btn ghost small" data-action="telegram-check">${e(t("بررسی اتصال","Check connection"))}</button></div><p class="switch-hint">${e(t("پس از تغییر توکن، اتصال سرویس سایت و ادمین‌بودن همان ربات در کانال را بررسی کن.","After changing a token, check the website connection and that the same bot is a channel administrator."))}</p>${result}</article>`;
}
function renderAdmin() {
 const a=state.admin;if(!a)return `<div class="loading">${e(t("در حال دریافت مدیریت…","Loading management…"))}</div>`;
 const tab=state.adminTab||"overview";
 const tabs=`<nav class="admin-tabs" aria-label="${e(t("بخش‌های مدیریت","Management sections"))}">${[["overview",t("کنترل و آمار","Controls & stats")],["users",t("کاربران","Users")],["work",t("مأموریت و درخواست‌ها","Missions & requests")],["audit",t("سوابق مدیریت","Admin history")]].map(([key,label])=>`<button class="btn ${tab===key?"primary":"ghost"}" data-action="admin-tab" data-tab="${key}" ${tab===key?'aria-current="page"':""}>${e(label)}</button>`).join("")}</nav>`;
 if(tab==="work")return tabs+renderAdminLegacy();
 let body="";
 if(tab==="users") {
  const page=state.userPage||a.user_page;
  body=`<article class="card"><form class="admin-search" data-form="admin-search"><div class="field"><label for="user-search">${e(t("جست‌وجو با آیدی عددی یا کیف پول","Search by user ID or wallet"))}</label><input id="user-search" name="q" value="${e(state.userQuery||"")}" maxlength="100"></div><button class="btn primary" type="submit">${e(t("جست‌وجو","Search"))}</button></form><p class="switch-hint">${n(page.total)} ${e(t("حساب یافت شد","accounts found"))}</p><div class="table-wrap"><table><thead><tr><th>${e(t("کاربر","User"))}</th><th>${e(t("دعوت","Referrals"))}</th><th>${e(t("موجودی","Balance"))}</th><th>${e(t("سطح","Level"))}</th><th>${e(t("مدیریت","Manage"))}</th></tr></thead><tbody>${page.users.map(u=>`<tr><td class="mono">${e(u.user_id)} ${u.suspended?`<span class="badge red">${e(t("تعلیق","Suspended"))}</span>`:!u.registered?`<span class="badge">${e(t("ناقص","Incomplete"))}</span>`:""}</td><td>${n(u.referrals)}</td><td>${n(u.unpaid)} PRS</td><td>${tierMark(u.level.id)} ${e(field(u.level,"name"))}</td><td><button class="btn ghost small" data-action="admin-user" data-id="${e(u.user_id)}">${e(t("جزئیات و عملیات","Details & actions"))}</button></td></tr>`).join("")}</tbody></table></div><div class="account-actions"><button class="btn ghost" data-action="admin-users-page" data-page="${page.page-1}" ${page.page<=1?"disabled":""}>${e(t("قبلی","Previous"))}</button><span>${n(page.page)}</span><button class="btn ghost" data-action="admin-users-page" data-page="${page.page+1}" ${page.page*page.page_size>=page.total?"disabled":""}>${e(t("بعدی","Next"))}</button></div></article>`;
 } else if(tab==="audit") {
  body=`<article class="card"><div class="section-heading"><h2>${e(t("۵۰ عملیات اخیر مدیران","50 recent admin actions"))}</h2><a class="btn ghost small" href="/api/admin/export/audit" download>${e(t("خروجی کامل CSV","Export full CSV"))}</a></div>${a.audit.length?a.audit.map(row=>`<div class="admin-row"><div><h3>${e(adminActionLabel(row.action))}</h3><p>${e(t("مدیر ","Admin "))}${e(row.admin_id)} · ${e(t("شناسه ","Target "))}${e(row.target)}</p><p>${e(date(row.created_at,true))}</p>${row.details.reason?`<p>${e(row.details.reason)}</p>`:""}${row.details.amount?`<strong>${n(row.details.amount)} PRS</strong>`:""}</div></div>`).join(""):empty(t("هنوز عملیاتی ثبت نشده است.","No admin actions recorded yet."))}</article>`;
 } else {
  const s=a.stats,c=a.controls;
  body=`<div class="admin-stats">${[[a.users,t("کاربر ثبت‌شده","Registered users")],[s.active_mining,t("دوره فعال ماین","Active mining cycles")],[s.earned,t("کل پاداش ثبت‌شده PRS","Total rewards PRS")],[s.paid,t("پرداخت ثبت‌شده PRS","Payments recorded PRS")],[s.mining_spent,t("ماین دریافت‌شده PRS","Mining collected PRS")],[s.mining_reserved,t("رزرو دوره‌های ماین PRS","Reserved mining PRS")],[s.suspended,t("حساب تعلیق‌شده","Suspended accounts")],[Math.max(0,s.campaign_limit-s.earned-s.mining_reserved),t("ظرفیت باقی‌مانده PRS","Remaining campaign PRS")]].map(([value,label])=>`<article class="card admin-stat"><strong>${n(value)}</strong><span>${e(label)}</span></article>`).join("")}</div><div class="split-grid"><article class="card"><h2>${e(t("کنترل کمپین و ماین","Campaign & mining controls"))}</h2><form data-form="admin-controls"><div class="field account-section"><label for="campaign-state">${e(t("وضعیت پاداش‌های کمپین","Campaign rewards"))}</label><select id="campaign-state" name="paused"><option value="0" ${!c.paused?"selected":""}>${e(t("فعال","Active"))}</option><option value="1" ${c.paused?"selected":""}>${e(t("توقف موقت پاداش‌ها","Pause rewards"))}</option></select></div><div class="field"><label for="mining-state">${e(t("شروع دوره جدید ماین","New mining cycles"))}</label><select id="mining-state" name="mining_enabled"><option value="1" ${c.mining.enabled?"selected":""}>${e(t("فعال","Enabled"))}</option><option value="0" ${!c.mining.enabled?"selected":""}>${e(t("متوقف؛ دریافت دوره‌های قبلی مجاز","Paused; existing cycles can be collected"))}</option></select></div><div class="field"><label for="mining-budget">${e(t("بودجه کل ماین PRS","Total mining budget PRS"))}</label><input id="mining-budget" type="number" name="mining_budget" min="${c.mining.spent+c.mining.reserved}" max="300000000" step="1" required value="${c.mining.budget}"><small>${e(t("این سقف شامل پاداش مصرف‌شده و دوره‌های رزروشده است.","This cap includes spent rewards and reserved cycles."))}</small></div><button class="btn primary" type="submit">${e(t("ذخیره تنظیمات","Save controls"))}</button></form></article><article class="card"><h2>${e(t("اطلاعیه داخل پنل","Portal announcement"))}</h2><form data-form="admin-announcement"><div class="field account-section"><label for="announcement">${e(t("متن اطلاعیه برای تمام کاربران؛ برای حذف خالی بگذار","Announcement for all users; leave empty to remove"))}</label><textarea id="announcement" name="announcement" maxlength="1500">${e(c.announcement)}</textarea></div><button class="btn primary" type="submit">${e(t("ثبت اطلاعیه","Save announcement"))}</button></form><div class="account-section"><h3>${e(t("گزارش‌ها","Reports"))}</h3><div class="account-actions"><a class="btn ghost" href="/api/admin/export/users" download>${e(t("کاربران CSV","Users CSV"))}</a><a class="btn ghost" href="/api/admin/export/payments" download>${e(t("پرداخت‌ها CSV","Payments CSV"))}</a></div><p class="switch-hint">${e(t("همه تاریخ‌ها و مهلت‌ها به وقت تهران هستند.","All dates and deadlines use Tehran time."))}</p></div></article></div><article class="card account-section"><h2>${e(t("۵۰ درخواست پرداخت اخیر","50 recent payment requests"))}</h2>${a.recent_payments.length?a.recent_payments.map(p=>`<div class="admin-row"><div><h3>${e(p.user_id)} · ${n(p.amount)} PRS</h3><p>${e(date(p.created_at,true))}</p></div>${statusBadge(p.status)}</div>`).join(""):empty(t("هنوز درخواستی نیست.","No payment requests yet."),"wallet")}</article>`;
 }
 return `${heading("PHASE 02 · MANAGEMENT",t("مدیریت ایردراپ","Airdrop management"),t("کاربران، بودجه، پاداش‌ها و سوابق را مدیریت کن.","Manage users, budgets, rewards and activity records."))}${tabs}${tab==="overview"?renderTelegramCheck():""}${body}`;
}
async function adminUserModal(uid) {
 const detail=await api(`/api/admin/users/${encodeURIComponent(uid)}`),u=detail.user;
 modal(t("مدیریت حساب ","Manage account ")+uid,`<div class="detail-line"><span>${e(t("سطح","Level"))}</span><strong>${tierMark(u.level.id)} ${e(field(u.level,"name"))}</strong></div><div class="detail-line"><span>${e(t("موجودی ذخیره‌شده","Stored balance"))}</span><strong>${n(u.unpaid)} PRS</strong></div><div class="detail-line"><span>${e(t("دعوت / دعوت‌کننده","Referrals / inviter"))}</span><strong>${n(u.referrals)} / ${e(u.referred_by||"—")}</strong></div><p class="evidence mono">${e(u.wallet||"—")}</p><form data-form="admin-user-action" data-id="${e(uid)}" data-request-id="${crypto.randomUUID()}"><div class="field"><label for="user-action">${e(t("عملیات","Action"))}</label><select id="user-action" name="action"><option value="bonus">${e(t("ثبت پاداش دستی","Record manual reward"))}</option><option value="unlock_wallet">${e(t("اجازه یک اصلاح کیف پول","Allow one wallet edit"))}</option><option value="${u.suspended?"resume":"suspend"}">${e(u.suspended?t("رفع تعلیق","Restore account"):t("تعلیق حساب","Suspend account"))}</option></select></div><div class="field"><label for="user-bonus">${e(t("مبلغ؛ فقط برای پاداش دستی PRS","Amount; manual reward only PRS"))}</label><input id="user-bonus" name="amount" type="number" min="1" max="300000000" step="1"></div><div class="field"><label for="user-reason">${e(t("دلیل عملیات؛ در سابقه ثبت می‌شود","Reason; saved in the audit history"))}</label><textarea id="user-reason" name="reason" minlength="3" maxlength="400" required></textarea></div><button class="btn primary full" type="submit">${e(t("ثبت عملیات","Apply action"))}</button></form><details class="account-section"><summary>${e(t("اصلاح کیف پول توسط مدیر","Admin wallet correction"))}</summary><form data-form="admin-wallet" data-id="${e(uid)}"><div class="field"><label for="admin-wallet">${e(t("آدرس عمومی BNB","BNB public address"))}</label><input id="admin-wallet" class="wallet-input" name="wallet" value="${e(u.wallet)}" pattern="0x[a-fA-F0-9]{40}" maxlength="42" required></div><button class="btn ghost" type="submit">${e(t("ذخیره آدرس","Save address"))}</button></form></details><details class="account-section"><summary>${e(t("دعوت‌های مرتبط","Linked referrals"))} (${n(detail.referrals.length)})</summary>${detail.referrals.map(r=>`<p class="detail-line">${e(r.user_id)} · ${e(r.registered?t("ثبت‌نام کامل","Registered"):t("ثبت‌نام ناقص","Incomplete"))}</p>`).join("")}</details><h3 class="account-section">${e(t("فعالیت‌های اخیر","Recent activity"))}</h3>${historyList(detail.history.slice(0,10))}`);
}
function phaseTwoClick(button) {
 const action=button.dataset.action;
 if(action==="admin-tab"){state.adminTab=button.dataset.tab;render();return true;}
 if(action==="archive-mission"){archiveMissionModal(button.dataset.id);return true;}
 if(!["mining-start","mining-claim","admin-user","admin-users-page","restore-mission","telegram-check"].includes(action))return false;
 busy(button,async()=>{
  if(action==="mining-start"){await api("/api/mining/start","POST");await refresh();toast(t("دوره ۸ساعته شروع شد.","Your 8-hour cycle has started."));}
  else if(action==="mining-claim"){const result=await api("/api/mining/claim","POST",{cycle_id:state.me.mining.cycle.id});await refresh();if(!result.already_claimed)celebrateHeritageReward(result.amount);toast(t(`${n(result.amount)} PRS به حسابت اضافه شد.`,`${n(result.amount)} PRS added to your balance.`));}
  else if(action==="restore-mission"){await api(`/api/admin/missions/${encodeURIComponent(button.dataset.id)}/archive`,"POST",{archived:false});await refresh();toast(t("مأموریت بازگردانده شد؛ برای شروع آن را فعال کن.","Mission restored. Activate it when ready."));}
  else if(action==="telegram-check"){state.telegramCheck=await api("/api/admin/telegram/check","POST",{});render();}
  else if(action==="admin-user")await adminUserModal(button.dataset.id);
  else {state.userPage=await api(`/api/admin/users?q=${encodeURIComponent(state.userQuery||"")}&page=${Number(button.dataset.page)}`);render();}
 });
 return true;
}
function handlePhaseTwoForm(form,submitter,fd) {
 const kind=form.dataset.form;
 if(!["admin-search","admin-controls","admin-announcement","admin-user-action","admin-wallet","archive-mission"].includes(kind))return false;
 busy(submitter,async()=>{
  if(kind==="admin-search"){state.userQuery=String(fd.get("q")||"");state.userPage=await api(`/api/admin/users?q=${encodeURIComponent(state.userQuery)}`);render();return;}
  if(kind==="archive-mission"){await api(`/api/admin/missions/${encodeURIComponent(form.dataset.id)}/archive`,"POST",{archived:true});closeModal();toast(t("مأموریت از فهرست حذف شد؛ سوابق و پاداش‌ها محفوظ است.","Mission removed from the list. Rewards and history are preserved."));}
  else if(kind==="admin-controls")await api("/api/admin/controls","POST",{paused:fd.get("paused")==="1",mining_enabled:fd.get("mining_enabled")==="1",mining_budget:Number(fd.get("mining_budget"))});
  else if(kind==="admin-announcement")await api("/api/admin/controls","POST",{announcement:fd.get("announcement")});
  else if(kind==="admin-wallet"){await api(`/api/admin/users/${encodeURIComponent(form.dataset.id)}/wallet`,"POST",{wallet:fd.get("wallet")});closeModal();}
  else {await api(`/api/admin/users/${encodeURIComponent(form.dataset.id)}/action`,"POST",{action:fd.get("action"),amount:Number(fd.get("amount")),reason:fd.get("reason"),request_id:form.dataset.requestId});closeModal();}
  if(state.userPage)state.userPage=await api(`/api/admin/users?q=${encodeURIComponent(state.userQuery||"")}&page=${state.userPage.page}`);
  await refresh();toast(t("تغییرات ثبت شد.","Changes saved."));
 });
 return true;
}
setInterval(()=>{if(!document.hidden)updatePhaseTwoClocks();},1000);

// PRS Heritage theme: presentation only; existing API and account rules stay in place.
const heritageMotionQuery = typeof window.matchMedia === "function"
  ? window.matchMedia("(prefers-reduced-motion: reduce)") : null;
let heritageMotionEnabled = true;
let heritageRewardTimer;
try { heritageMotionEnabled = localStorage.getItem("prs-motion") !== "off"; } catch (_) {}

function heritageAllowsMotion() {
  return heritageMotionEnabled && !heritageMotionQuery?.matches && !document.hidden;
}

function syncThemeMotion() {
  const active = heritageAllowsMotion();
  document.documentElement.dataset.motion = active ? "on" : "off";
  document.querySelectorAll(".motion-toggle").forEach(button => {
    button.setAttribute("aria-pressed", String(active));
    button.setAttribute("aria-label", t("حرکت‌های تزئینی", "Decorative motion"));
    button.title = heritageMotionQuery?.matches
      ? t("حرکت‌ها طبق تنظیم کاهش حرکت دستگاه خاموش‌اند", "Motion follows your device's reduced-motion setting")
      : active ? t("توقف حرکت‌های تزئینی", "Pause decorative motion")
        : t("فعال‌کردن حرکت‌های تزئینی", "Enable decorative motion");
    button.disabled = Boolean(heritageMotionQuery?.matches);
    button.innerHTML = active
      ? '<svg viewBox="0 0 24 24" class="icon" aria-hidden="true"><path d="M9 5v14M15 5v14"/></svg>'
      : '<svg viewBox="0 0 24 24" class="icon" aria-hidden="true"><path d="m9 5 10 7-10 7V5Z"/></svg>';
  });
  if (!active) clearHeritageReward();
}

function heritageBanner() {
  const label = t("تصویر هنری آرامگاه کوروش با سرستون‌های تخت جمشید و نقش سربازان هخامنشی",
    "Artistic tribute to the Tomb of Cyrus, Persepolis capitals and Achaemenid guards");
  return '<section class="heritage-hero" aria-label="' + e(t("میراث PRS", "The PRS heritage")) + '">' +
    '<div class="heritage-copy"><div class="heritage-kicker"><span class="heritage-spark" aria-hidden="true">✦</span>' +
    '<span>PRS · PERSEPOLIS</span></div><h2>' + e(t("از ریشه‌های بزرگ،\nبه فردایی مشترک.", "A timeless heritage.\nA shared tomorrow.")) + '</h2>' +
    '<p>' + e(t("مأموریت امروزت را انتخاب کن و به ساختن جامعه PRS کمک کن.", "Choose your next mission and help build the PRS community.")) + '</p>' +
    '<button class="btn primary" type="button" data-action="navigate" data-route="missions">' +
    icon("target") + e(t("کشف مأموریت‌ها", "Explore missions")) + icon("arrow") + '</button>' +
    '<div class="heritage-caption"><span></span>PASARGADAE · PERSEPOLIS</div></div>' +
    '<div class="heritage-art" role="img" aria-label="' + e(label) + '">' +
    '<span class="heritage-dust dust-one" aria-hidden="true">✦</span><span class="heritage-dust dust-two" aria-hidden="true">✧</span>' +
    '<span class="heritage-dust dust-three" aria-hidden="true">✦</span></div></section>';
}

function decorateHeritageRoute() {
  const page = $("page");
  page.dataset.route = state.route;
  if (state.route !== "dashboard") return;
  page.querySelector(".page-title")?.insertAdjacentHTML("afterend", heritageBanner());
  const watermark = page.querySelector(".hero-watermark");
  if (watermark) watermark.innerHTML = '<img src="/static/mark.svg" width="76" height="76" alt="">';
  const dailyIcon = page.querySelector(".daily-card .card-top .icon-tile");
  if (dailyIcon) dailyIcon.innerHTML = '<span class="heritage-gift" aria-hidden="true">🎁</span>';
}

function clearHeritageReward() {
  clearTimeout(heritageRewardTimer);
  $("heritage-reward")?.remove();
}

function celebrateHeritageReward(amount) {
  clearHeritageReward();
  const value = Number(amount);
  if (!heritageAllowsMotion() || !Number.isFinite(value) || value <= 0) return;
  const layer = document.createElement("div");
  layer.id = "heritage-reward";
  layer.className = "heritage-reward";
  layer.setAttribute("aria-hidden", "true");
  for (let i = 0; i < 12; i++) {
    const particle = document.createElement("span");
    particle.className = "reward-particle";
    if (i % 3 === 0) {
      const coin = document.createElement("img");
      coin.src = "/static/mark.svg";
      coin.alt = "";
      coin.width = coin.height = 26;
      particle.append(coin);
    } else particle.textContent = i % 2 ? "✦" : "✧";
    layer.append(particle);
  }
  const medallion = document.createElement("div");
  medallion.className = "reward-medallion";
  const logo = document.createElement("img");
  logo.src = "/static/mark.svg";
  logo.alt = "";
  logo.width = logo.height = 84;
  const label = document.createElement("strong");
  label.textContent = "+" + n(value) + " PRS";
  medallion.append(logo, label);
  layer.append(medallion);
  document.body.append(layer);
  heritageRewardTimer = setTimeout(clearHeritageReward, 2200);
}

function initHeritageTheme() {
  document.documentElement.dataset.heritage = "prs-2026";
  const themeMeta = document.querySelector('meta[name="theme-color"]');
  if (themeMeta) themeMeta.content = "#090909";
  document.querySelectorAll(".brand-mark").forEach(mark => {
    const image = document.createElement("img");
    image.src = "/static/mark.svg";
    image.alt = "";
    image.width = image.height = 56;
    mark.replaceChildren(image);
  });
  const orbit = document.querySelector(".login-orbit");
  if (orbit) {
    orbit.className = "heritage-plaque";
    orbit.innerHTML = '<span class="heritage-plaque-line"></span><span>PASARGADAE · PERSEPOLIS</span><span class="heritage-plaque-line"></span>';
  }
  const eyebrow = document.querySelector(".login-story-copy .eyebrow");
  if (eyebrow) eyebrow.textContent = "A CULTURE. A COMMUNITY. A SHARED FUTURE.";
  const story = document.querySelector(".login-story");
  if (story) {
    const sparks = document.createElement("div");
    sparks.className = "heritage-atmosphere";
    sparks.setAttribute("aria-hidden", "true");
    sparks.innerHTML = '<span>✦</span><span>✧</span><span>✦</span><span>✧</span>';
    story.append(sparks);
  }
  const context = document.querySelector(".topbar-context");
  if (context) {
    const brand = document.createElement("a");
    brand.className = "header-brand";
    brand.href = "#dashboard";
    brand.setAttribute("aria-label", "PRS");
    brand.innerHTML = '<img src="/static/mark.svg" width="42" height="42" alt="">';
    context.prepend(brand);
  }
  [document.querySelector(".login-form-wrap"), document.querySelector(".topbar-actions")].forEach(parent => {
    if (!parent) return;
    const button = document.createElement("button");
    button.type = "button";
    button.className = "motion-toggle";
    button.addEventListener("click", () => {
      heritageMotionEnabled = !heritageMotionEnabled;
      try { localStorage.setItem("prs-motion", heritageMotionEnabled ? "on" : "off"); } catch (_) {}
      syncThemeMotion();
    });
    parent.prepend(button);
  });
  heritageMotionQuery?.addEventListener?.("change", syncThemeMotion);
  document.addEventListener("visibilitychange", syncThemeMotion);
  window.addEventListener("pagehide", clearHeritageReward);
  syncThemeMotion();
}

initHeritageTheme();
init();
